import {DFPlayer} from './expansion-dfplayer.js';
import {UARTReceiver,UARTTransmitter} from './uart-lines.js';
import {poweredDevice,pinVoltage,logic} from './bus-electrical.js';
const format={period:16000000/9600,bits:8,stops:1,parity:null};
function nmea(body){let n=0;for(const c of body)n^=c.charCodeAt(0);return '$'+body+'*'+n.toString(16).toUpperCase().padStart(2,'0')+'\r\n';}
const coordinate=(value,latitude)=>{const v=Math.abs(value),d=Math.floor(v);return String(d).padStart(latitude?2:3,'0')+((v-d)*60).toFixed(4).padStart(7,'0');};
export function attachExpansionUART(runtime,engine,initial){let project=initial,states=new Map(),disposed=false,busy=false;const cpu=runtime.cpu,drives=new Map();
 const drive=(id,pin,value)=>{const k=id+':'+pin;if(drives.get(k)===value)return;drives.set(k,value);commit();};
 const commit=()=>engine.setDrivers('expansion-uart',[...drives].filter(([,v])=>v!==null).map(([endpoint,v])=>({endpoint,voltage:v?3.3:0,ohms:50})));
 const reply=(d,cmd,param=0)=>{const b=[0x7e,0xff,6,cmd,0,param>>8,param&255],sum=-(b.slice(1).reduce((a,b)=>a+b,0))&65535;for(const v of [...b,sum>>8,sum&255,0xef])d.tx.enqueue(v,format);};
 const armPlayer=d=>{const at=d.player.nextEvent(cpu.cycles);if(at===d.eventAt)return;d.eventAt=at;const token=++d.playerEpoch;if(at!==null)cpu.addClockEvent(()=>{if(disposed||token!==d.playerEpoch)return;d.eventAt=null;refresh();},Math.max(1,at-cpu.cycles));};
 const receive=(d,f)=>{if(f.error||!d.powered)return;d.player.receive(f.value,cpu.cycles);drive(d.id,'BUSY',!d.player.playing);armPlayer(d);};
 const schedule=d=>{const token=++d.epoch;cpu.addClockEvent(()=>{if(disposed||token!==d.epoch||!d.powered)return;const c=project.components.find(c=>c.id===d.id),lat=c.params.latitude??41.0082,lon=c.params.longitude??28.9784,ns=lat>=0?'N':'S',ew=lon>=0?'E':'W',time='120000.00',a=coordinate(lat,true),b=coordinate(lon,false);const lines=nmea('GPRMC,'+time+',A,'+a+','+ns+','+b+','+ew+',0.00,0.00,191026,,,A')+nmea('GPGGA,'+time+','+a+','+ns+','+b+','+ew+',1,08,0.9,30.0,M,0.0,M,,');for(const v of new TextEncoder().encode(lines))d.tx.enqueue(v,format);d.sentences+=2;schedule(d);},16000000);};
 const refresh=()=>{if(disposed||busy)return;busy=true;try{for(const d of states.values()){const p=poweredDevice(engine.solution,d.id,{min:2.7,max:5.5}),was=d.powered;Object.assign(d,p);if(!d.powered){if(was){d.player?.reset();d.playerEpoch++;d.epoch++;d.tx.cancel();d.rx?.cancel();drive(d.id,'TX',null);drive(d.id,'BUSY',null);}continue;}if(!was){drive(d.id,'TX',true);if(d.type==='gps')schedule(d);else drive(d.id,'BUSY',!d.playing);}if(d.player){d.player.setTracks(project.components.find(c=>c.id===d.id)?.params.audioTracks);d.player.tick(cpu.cycles);drive(d.id,'BUSY',!d.player.playing);armPlayer(d);}d.rx?.observe();}}finally{busy=false;}};
 const update=()=>{const ids=new Set();for(const c of project.components.filter(c=>['gps','dfplayer'].includes(c.type))){ids.add(c.id);if(!states.has(c.id)){const d={id:c.id,type:c.type,powered:false,epoch:0,playing:false,track:1,volume:20,commands:0,errors:0,sentences:0};d.tx=new UARTTransmitter(cpu,value=>drive(c.id,'TX',value));if(c.type==='dfplayer'){d.playerEpoch=0;d.player=new DFPlayer((cmd,value)=>reply(d,cmd,value));d.rx=new UARTReceiver(cpu,()=>logic(pinVoltage(engine.solution,c.id,'RX'),3.3),()=>d.powered?format:null,f=>receive(d,f));}states.set(c.id,d);}}for(const[id,d]of states)if(!ids.has(id)){d.epoch++;d.tx.cancel();d.rx?.cancel();states.delete(id);for(const p of ['TX','BUSY'])drives.delete(id+':'+p);}refresh();commit();};
 update();const off=engine.subscribe(refresh);return{updateProject(next){project=next;update();},snapshot(){refresh();return{modules:Object.fromEntries([...states].map(([id,d])=>[id,{type:d.type,powered:d.powered,playing:d.playing,track:d.track,volume:d.volume,commands:d.commands,errors:d.errors,unsupported:d.unsupported,sentences:d.sentences,...d.player?.state()}]))};},dispose(){disposed=true;off();for(const d of states.values()){d.epoch++;d.tx.cancel();d.rx?.cancel();}engine.setDrivers('expansion-uart',[]);}};
}
